<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../app/helpers.php';require_login();require_role('admin','staff');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));if($name===''){flash('danger','Tên danh mục là bắt buộc.');redirect('/categories.php');}try{$st=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$st->execute([$name,$desc]);flash('success','Đã thêm danh mục.');}catch(PDOException $e){flash('danger','Tên danh mục có thể đã tồn tại.');}redirect('/categories.php');}
$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.is_active=1 GROUP BY c.id ORDER BY c.name')->fetchAll();$pageTitle='Danh mục';require __DIR__.'/../app/layout/header.php';?>
<div class="page-heading mb-3"><div><h1 class="h3">Danh mục sản phẩm</h1><p class="text-secondary mb-0">Nhóm sản phẩm để dễ quản lý.</p></div></div><div class="row g-4"><div class="col-12 col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Thêm danh mục</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="mb-3"><label class="form-label">Tên danh mục</label><input name="name" class="form-control" required></div><div class="mb-3"><label class="form-label">Mô tả</label><textarea name="description" class="form-control" rows="3"></textarea></div><button class="btn btn-primary">Lưu danh mục</button></form></div></div></div><div class="col-12 col-lg-8"><div class="card"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Tên</th><th>Mô tả</th><th>Số sản phẩm</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?= (int)$r['product_count'] ?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require __DIR__.'/../app/layout/footer.php';?>
